# Whole board visible: the drawn board touches none of the HUD panels or the
# reserve rails that flank it.
var m = tree.current_scene
var board = SceneRefs.board_screen_rect(m)
var hits = []
for n in ["HUD_Bottom", "PhaseStrip", "GameLogPanel", "HUD_Right"]:
	var c = m.get_node_or_null(n)
	if c != null and c.is_visible_in_tree() and c.get_global_rect().intersects(board):
		hits.append(n)
var tray = m.get_node_or_null("ReservesTray")
if tray != null:
	for p in [1, 2]:
		var rail = tray.rail_for(p)
		if rail != null and rail.is_visible_in_tree() and rail.get_global_rect().intersects(board):
			hits.append("rail_%d" % p)
return hits.size()

# Animation: samples taken every frame while F was held.
var m = tree.current_scene
var s = m.get_meta("t13_samples", [])
var z0 = 0.3
var z1 = m.view_zoom
var n = 0
for e in s:
	var z = float(e["vz"])
	if abs(z - z0) > 0.001 and abs(z - z1) > 0.001:
		n += 1
return n

var m = tree.current_scene
var s = m.get_meta("t13_samples", [])
var z0 = 0.3
var z1 = m.view_zoom
var prev = z0
var away = 0
for e in s:
	var z = float(e["vz"])
	if (z - prev) * (z1 - z0) < -0.000001:
		away += 1
	prev = z
return away

var m = tree.current_scene
var s = m.get_meta("t13_samples", [])
var z0 = 0.3
var z1 = m.view_zoom
var prev = z0
var biggest = 0.0
for e in s:
	var z = float(e["vz"])
	biggest = max(biggest, abs(z - prev))
	prev = z
biggest = max(biggest, abs(z1 - prev))
return biggest / max(abs(z1 - z0), 0.000001)

var m = tree.current_scene
var s = m.get_meta("t13_samples", [])
var z1 = m.view_zoom
var n = 0
for e in s:
	var c = float(e["cz"])
	if abs(c - 0.3) > 0.001 and abs(c - z1) > 0.001:
		n += 1
return n

var s = tree.current_scene.get_meta("t13_samples", [])
var n = 0
for e in s:
	if e["held"]:
		n += 1
return n
